<script setup>
import { ref,onMounted } from 'vue';
import { useMessage } from 'naive-ui';
import { api } from '../../api';
const count=ref(10),days=ref(30),codes=ref([]),rows=ref([]),busy=ref(false),offset=ref(0),message=useMessage();
async function load(){try{rows.value=(await api.fetch('/admin/invitations?offset='+offset.value,{quiet:true})).results||[];}catch(e){message.error(e.message);}}
async function generate(){if(busy.value)return;busy.value=true;try{codes.value=(await api.fetch('/admin/invitations',{method:'POST',quiet:true,body:JSON.stringify({count:count.value,days:days.value})})).codes;offset.value=0;await load();message.success(`已生成 ${codes.value.length} 个邀请码`);}catch(e){message.error(e.message);}finally{busy.value=false;}}
async function copy(){try{await navigator.clipboard.writeText(codes.value.map(x=>x.code).join('\n'));message.success('已复制');}catch{message.error('复制失败，请选中文本手动复制');}}
function download(){const url=URL.createObjectURL(new Blob([codes.value.map(x=>x.code).join('\r\n')],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='ionacs-invitations.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function revoke(id){try{await api.fetch('/admin/invitations/'+id,{method:'DELETE',quiet:true});await load();}catch(e){message.error(e.message);}}
const date=n=>n?new Date(n*1000).toLocaleString('zh-CN'):'—';
const state=r=>r.used_at?'已使用':r.revoked_at?'已撤销':r.expires_at<Date.now()/1000?'已过期':'可使用';
onMounted(load);
</script>
<template><section class="admin-panel"><h2>邀请新成员</h2><p>每个邀请码只能注册一个邮箱。完整邀请码仅在生成时显示，请复制或下载保存。</p><form class="invite-form" @submit.prevent="generate"><label>生成数量<n-input-number v-model:value="count" :min="1" :max="100" :precision="0" /></label><label>有效天数<n-input-number v-model:value="days" :min="1" :max="365" :precision="0" /></label><button class="primary-button" :disabled="busy">{{busy?'正在生成…':'生成邀请码'}}</button></form><div v-if="codes.length" class="invite-result"><div><strong>本次生成 {{codes.length}} 个邀请码</strong><button class="text-button" @click="copy">全部复制</button><button class="text-button" @click="download">下载文本</button></div><textarea readonly aria-label="新生成的邀请码" :value="codes.map(x=>x.code).join('\n')" rows="7"></textarea></div></section><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>邀请码尾号</th><th>状态</th><th>有效期至</th><th>注册邮箱</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><code>•••• {{r.hint}}</code></td><td>{{state(r)}}</td><td>{{date(r.expires_at)}}</td><td>{{r.used_by||'—'}}</td><td><button v-if="state(r)==='可使用'" class="text-button" @click="revoke(r.id)">撤销</button></td></tr><tr v-if="!rows.length"><td colspan="5">暂无邀请码</td></tr></tbody></table></div><div class="admin-pagination"><button class="outline-button" :disabled="offset===0" @click="offset-=100;load()">上一页</button><span>第 {{offset/100+1}} 页</span><button class="outline-button" :disabled="rows.length<100" @click="offset+=100;load()">下一页</button></div></template>
<style scoped>.invite-form{display:flex;gap:20px;align-items:end;flex-wrap:wrap;margin:24px 0}.invite-form label{display:grid;gap:8px}.invite-result textarea{width:100%;box-sizing:border-box;padding:16px;border:1px solid #dadce0;border-radius:8px;background:var(--surface,#fff);color:inherit;font:14px/1.8 monospace}.invite-result{margin-top:24px}</style>
